using MassageShop.API.Data;using MassageShop.API.Models.Entities;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace MassageShop.API.Controllers{[ApiController][Route("api/attendances")][Authorize]public class AttendancesController:ControllerBase{readonly AppDbContext db;public AttendancesController(AppDbContext d)=>db=d;[Authorize(Roles="ADMIN")][HttpGet]public async Task<IActionResult>All()=>Ok(await db.Attendances.Include(x=>x.Employee).ThenInclude(x=>x.User).Include(x=>x.WorkShift).ToListAsync());[Authorize(Roles="EMPLOYEE")][HttpPost("{shiftId}/check-in")]public async Task<IActionResult>CheckIn(int shiftId){var e=await db.Employees.FirstOrDefaultAsync(x=>x.UserId==int.Parse(User.FindFirst("userId")!.Value));if(e==null)return NotFound();if(await db.Attendances.AnyAsync(x=>x.WorkShiftId==shiftId))return BadRequest(new{message="Ca đã được chấm công"});var s=await db.WorkShifts.FindAsync(shiftId);if(s==null||s.EmployeeId!=e.Id)return Forbid();var now=DateTime.UtcNow;db.Add(new Attendance{EmployeeId=e.Id,WorkShiftId=shiftId,CheckInAt=now,LateMinutes=Math.Max(0,(int)(now.TimeOfDay-s.StartTime).TotalMinutes),Status=now.TimeOfDay>s.StartTime?"LATE":"ON_TIME"});await db.SaveChangesAsync();return Ok();}}}
